parameters.jsCode:
const events = $input.all().filter(item => item.json.id);

return [
  {
    json: {
      is_event_free: events.length === 0,
      conflicting_events: events.map(item => ({
        title: item.json.summary,
        start: item.json.start,
        end: item.json.end
      }))
    }
  }
];

